exercise.referenceSolution:
#include <iostream>
#include <map>
#include <print>
#include <string>

int main() {
    std::map<std::string, std::string> dict;
    std::string command, key;
    while (std::cin >> command >> key) {
        if (command == "set") {
            std::string value;
            std::cin >> value;
            dict[key] = value;
        } else if (command == "get") {
            if (auto it = dict.find(key); it != dict.end()) {
                std::println("{}: {}", key, it->second);
            } else {
                std::println("{}: нет", key);
            }
        } else {
            if (auto it = dict.find(key); it != dict.end()) {
                dict.erase(it);
                std::println("удалено {}", key);
            } else {
                std::println("{}: нет", key);
            }
        }
    }
    return 0;
}

