additionalExercises.referenceSolution:
#include <deque>
#include <functional>
#include <iostream>
#include <print>
#include <string>
#include <utility>

class ScopeGuard {
public:
    explicit ScopeGuard(std::function<void()> action) : action_(std::move(action)) {}
    ScopeGuard(const ScopeGuard &) = delete;
    ScopeGuard &operator=(const ScopeGuard &) = delete;
    ~ScopeGuard() {
        if (action_) {
            action_();
        }
    }

    void dismiss() {
        action_ = nullptr;
    }

private:
    std::function<void()> action_;
};

using Transaction = std::deque<ScopeGuard>;

void abort_last(std::deque<Transaction> &transactions) {
    Transaction &t = transactions.back();
    while (!t.empty()) {
        t.pop_back();
    }
    transactions.pop_back();
}

int main() {
    std::deque<Transaction> transactions;
    std::string command;
    while (std::cin >> command) {
        if (command == "begin") {
            transactions.emplace_back();
        } else if (command == "do") {
            std::string x;
            std::cin >> x;
            std::println("сделано {}", x);
            transactions.back().emplace_back([x] { std::println("откат {}", x); });
        } else if (command == "commit") {
            Transaction &t = transactions.back();
            for (ScopeGuard &guard : t) {
                guard.dismiss();
            }
            std::println("подтверждено {}", t.size());
            transactions.pop_back();
        } else {
            abort_last(transactions);
        }
    }
    while (!transactions.empty()) {
        abort_last(transactions);
    }
    return 0;
}

